/* From Uiverse.io by VashonG - Tags: flashy, animation, button */
.__UIV_SCOPE__ .code-button {
  display: inline-block;
  font-family: "Menlo", "Bitstream Vera Sans Mono", "DejaVu Sans Mono", "Monaco", "Consolas", monospace;
  margin: 1em;
  border-radius: 3px;
  background: #434d5a;
  border: none;
  padding: 1em 0;
  color: white;
  text-align: center;
  text-decoration: none;
  width: 9em;
  transition: all 0.2s ease, background-color 0.2s ease-in 0.15s, box-shadow 0.2s ease-in 0.15s, color 0s ease;
}

.__UIV_SCOPE__ .code-button__bracket, .__UIV_SCOPE__ .code-button__text, .__UIV_SCOPE__ .code-button__code {
  display: inline-block;
  margin-right: -3px;
  text-align: center;
  width: 0.5em;
  transition: all 0.2s ease, color 0s ease;
}

.__UIV_SCOPE__ .code-button__bracket {
  font-weight: normal;
}

.__UIV_SCOPE__ .code-button__text {
  opacity: 0;
  position: absolute;
  transition: all 0s ease;
}

.__UIV_SCOPE__ .code-button:hover {
  padding: 1em 0;
  transition: all 0.2s ease, background-color 0.2s ease-in 0.05s, box-shadow 0.2s ease-in 0.05s, color 0s ease;
}

.__UIV_SCOPE__ .code-button:hover .code-button__code, .__UIV_SCOPE__ .code-button:hover .code-button__text {
  width: 2em;
}

.__UIV_SCOPE__ .code-button:hover .code-button__code, .__UIV_SCOPE__ .code-button:hover .code-button__text, .__UIV_SCOPE__ .code-button:hover .code-button__bracket {
  transition: all 0.2s ease, color 0s ease;
}

.__UIV_SCOPE__ .code-button:hover .code-button__code {
  opacity: 0;
  position: absolute;
}

.__UIV_SCOPE__ .code-button:hover .code-button__text {
  opacity: 1;
  position: static;
}

.__UIV_SCOPE__ .code-button--color:hover {
  color: #434d5a;
}

.__UIV_SCOPE__ .code-button--color:hover.code-button--css {
  background-color: #aaffa9;
  box-shadow: inset 15px 5px 70px -10px #aaffa9, inset -15px -5px 70px -10px #11ffbd;
}

.__UIV_SCOPE__ .code-button--color:hover.code-button--html {
  background-color: #fc8f71;
  box-shadow: inset 15px 15px 90px -20px #fc8f71, inset -15px -5px 80px -10px #fcdcab;
}

.__UIV_SCOPE__ .code-button--color:hover.code-button--js {
  background-color: #87e1ed;
  box-shadow: inset 15px 15px 90px -20px #7996d1, inset -15px -5px 80px -10px #87e1ed;
}
